import { jev } from "../../core/client.ts";
import { noul } from "../../core/helpers.ts";
import type { NoulAnswer, Questions, State } from "../../core/types.ts";
import { readFileState } from "./read-state.ts";

export type Decide = (state: State, questions: Questions) => Promise<{ answers: Record<string, unknown>; usage?: unknown }>;

export interface FileBool {
  path: string;
  answer: boolean;
  noul: number;
  usage?: unknown;
}

export async function askFileBool(
  path: string,
  question: string,
  cwd: string,
  criteria: { yes?: string; no?: string } = {},
  decide: Decide = (s, q) => jev.systemOne(s, q),
): Promise<FileBool> {
  const state = await readFileState(path, cwd);
  const questions = { answer: noul(question, criteria.yes || criteria.no ? { true: criteria.yes, false: criteria.no } : undefined) };
  const { answers, usage } = await decide(state, questions);
  const a = answers.answer as NoulAnswer;
  return { path, answer: a.noul > 0.5, noul: a.noul, usage };
}

import { jev } from "../../core/client.ts";
import { choice } from "../../core/helpers.ts";
import type { ChoiceAnswer } from "../../core/types.ts";
import type { Decide } from "./ask-file-bool.ts";
import { readFileState } from "./read-state.ts";

export interface FileChoice {
  path: string;
  choice: string;
  confidence: number;
  probabilities: Record<string, number>;
  usage?: unknown;
}

export async function askFileChoice(
  path: string,
  question: string,
  options: Record<string, string>,
  cwd: string,
  decide: Decide = (s, q) => jev.systemOne(s, q),
): Promise<FileChoice> {
  const state = await readFileState(path, cwd);
  const criteria = { ...options };
  if (!("other" in criteria) && !("none" in criteria) && !("none_of_the_above" in criteria)) criteria.other = "None of the above";
  const { answers, usage } = await decide(state, { answer: choice(question, criteria) });
  const a = answers.answer as ChoiceAnswer;
  return { path, choice: a.choice, confidence: a.confidence, probabilities: a.probabilities, usage };
}

import { jev } from "../../core/client.ts";
import { score } from "../../core/helpers.ts";
import type { ScoreAnswer } from "../../core/types.ts";
import type { Decide } from "./ask-file-bool.ts";
import { readFileState } from "./read-state.ts";

export interface FileScore {
  path: string;
  score: number;
  top: number;
  nearest: string;
  confidence: number;
  legend: Record<string, string>;
  usage?: unknown;
}

export async function askFileScore(
  path: string,
  question: string,
  levels: string[],
  cwd: string,
  decide: Decide = (s, q) => jev.systemOne(s, q),
): Promise<FileScore> {
  const state = await readFileState(path, cwd);
  const { answers, usage } = await decide(state, { answer: score(question, levels) });
  const a = answers.answer as ScoreAnswer;
  const top = levels.length - 1;
  return { path, score: a.score, top, nearest: a.legend[String(Math.round(a.score))] ?? "", confidence: a.confidence, legend: a.legend, usage };
}
